// swift-tools-version: 5.9

import Foundation
import PackageDescription

// ROS 2 common_interfaces and tf2_msgs for Swift, one module per ROS package, generated by
// swift-ros2-gen from the upstream IDL pinned in idl.lock (Humble, Jazzy, Kilted, Lyrical). The
// generated sources are committed and the package has no submodules, so consumers receive no
// IDL. Depends only on swift-ros2-rosidl, so it never downloads native frameworks.

var dependencies: [Package.Dependency] = [
    .package(url: "https://github.com/swift-ros2/swift-ros2-rosidl.git", from: "1.0.0")
]
if ProcessInfo.processInfo.environment["SWIFT_ROS2_DOCS_BUILD"] == "1" {
    dependencies.append(.package(url: "https://github.com/apple/swift-docc-plugin", from: "1.3.0"))
}

func rosidl(_ name: String) -> Target.Dependency {
    .product(name: name, package: "swift-ros2-rosidl")
}

let core: [Target.Dependency] = [rosidl("SwiftROS2CDR"), rosidl("SwiftROS2Messages")]

// Module dependencies follow upstream package.xml; every module a generated file imports
// must be listed, or the module does not build.
let interfaces: [(name: String, dependencies: [Target.Dependency])] = [
    ("StdMsgs", [rosidl("BuiltinInterfaces")]),
    ("StdSrvs", []),
    ("GeometryMsgs", ["StdMsgs"]),
    ("SensorMsgs", ["StdMsgs", "GeometryMsgs", rosidl("BuiltinInterfaces")]),
    ("NavMsgs", ["StdMsgs", "GeometryMsgs", rosidl("BuiltinInterfaces")]),
    ("DiagnosticMsgs", ["StdMsgs"]),
    ("ShapeMsgs", ["GeometryMsgs"]),
    ("StereoMsgs", ["StdMsgs", "SensorMsgs"]),
    ("TrajectoryMsgs", ["StdMsgs", "GeometryMsgs", rosidl("BuiltinInterfaces")]),
    ("VisualizationMsgs", ["StdMsgs", "GeometryMsgs", "SensorMsgs", rosidl("BuiltinInterfaces")]),
    ("Tf2Msgs", ["GeometryMsgs", rosidl("BuiltinInterfaces"), rosidl("UniqueIdentifierMsgs")]),
]
let allInterfaces: [Target.Dependency] = interfaces.map { .target(name: $0.name) }

let package = Package(
    name: "swift-ros2-common-interfaces",
    platforms: [.iOS(.v16), .macOS(.v13), .macCatalyst(.v16), .visionOS(.v1)],
    products: interfaces.map { .library(name: $0.name, targets: [$0.name]) }
        + [.library(name: "CommonInterfaces", targets: ["CommonInterfaces"])],
    dependencies: dependencies,
    targets: interfaces.map { .target(name: $0.name, dependencies: core + $0.dependencies) }
        + [
            .target(name: "CommonInterfaces", dependencies: allInterfaces + [rosidl("BuiltinInterfaces")]),
            // The samples reach builtin_interfaces only (Header, Duration fields, LookupTransform's
            // goal): no sampled type has a UUID field, and nothing references action_msgs.
            .executableTarget(
                name: "CommonInterfacesOracleCorpus",
                dependencies: core + allInterfaces + [rosidl("BuiltinInterfaces")]),
            .testTarget(
                name: "CommonInterfacesTests",
                dependencies: core + ["CommonInterfaces"]),
            .testTarget(
                name: "CommonInterfacesUmbrellaTests",
                dependencies: ["CommonInterfaces"]),
        ]
)
